CREATE TABLE vietnam_provinces(name TEXT PRIMARY KEY NOT NULL);
INSERT INTO vietnam_provinces(name) VALUES ('Hà Nội'),('Huế'),('Hải Phòng'),('Đà Nẵng'),('Hồ Chí Minh'),('Cần Thơ'),('Tuyên Quang'),('Cao Bằng'),('Lai Châu'),('Lào Cai'),('Thái Nguyên'),('Điện Biên'),('Lạng Sơn'),('Sơn La'),('Phú Thọ'),('Bắc Ninh'),('Quảng Ninh'),('Hưng Yên'),('Ninh Bình'),('Thanh Hóa'),('Nghệ An'),('Hà Tĩnh'),('Quảng Trị'),('Quảng Ngãi'),('Gia Lai'),('Khánh Hòa'),('Lâm Đồng'),('Đắk Lắk'),('Đồng Nai'),('Tây Ninh'),('Vĩnh Long'),('Đồng Tháp'),('An Giang'),('Cà Mau');
ALTER TABLE suppliers ADD COLUMN province_name TEXT REFERENCES vietnam_provinces(name) ON DELETE RESTRICT;
CREATE UNIQUE INDEX suppliers_tax_code_unique ON suppliers(replace(replace(trim(tax_code),'-',''),' ','') COLLATE NOCASE) WHERE tax_code IS NOT NULL AND length(trim(tax_code))>0;
CREATE TABLE supplier_code_sequence(id INTEGER PRIMARY KEY CHECK(id=1),last_value INTEGER NOT NULL CHECK(last_value BETWEEN 0 AND 99999));
CREATE TRIGGER supplier_rules_insert BEFORE INSERT ON suppliers WHEN NEW.province_name IS NULL OR length(NEW.code)!=8 OR NEW.code NOT GLOB 'NCC[0-9][0-9][0-9][0-9][0-9]' OR substr(NEW.code,4)='00000' BEGIN SELECT RAISE(ABORT,'SUPPLIER_INVALID_FIELDS'); END;
CREATE TRIGGER supplier_rules_update BEFORE UPDATE OF code,province_name ON suppliers WHEN NEW.province_name IS NULL OR (NEW.code!=OLD.code AND (length(NEW.code)!=8 OR NEW.code NOT GLOB 'NCC[0-9][0-9][0-9][0-9][0-9]' OR substr(NEW.code,4)='00000')) BEGIN SELECT RAISE(ABORT,'SUPPLIER_INVALID_FIELDS'); END;
CREATE TRIGGER supplier_linked_deactivate BEFORE UPDATE OF is_active ON suppliers WHEN NEW.is_active=0 AND EXISTS(SELECT 1 FROM inventory_documents WHERE supplier_id=NEW.id) BEGIN SELECT RAISE(ABORT,'SUPPLIER_HAS_DOCUMENTS'); END;
CREATE TRIGGER supplier_linked_delete BEFORE DELETE ON suppliers WHEN EXISTS(SELECT 1 FROM inventory_documents WHERE supplier_id=OLD.id) BEGIN SELECT RAISE(ABORT,'SUPPLIER_HAS_DOCUMENTS'); END;
CREATE TRIGGER document_supplier_insert BEFORE INSERT ON inventory_documents WHEN NEW.supplier_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM suppliers WHERE id=NEW.supplier_id AND is_active=1) BEGIN SELECT RAISE(ABORT,'SUPPLIER_INACTIVE'); END;
CREATE TRIGGER document_supplier_update BEFORE UPDATE OF supplier_id ON inventory_documents WHEN NEW.supplier_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM suppliers WHERE id=NEW.supplier_id AND is_active=1) BEGIN SELECT RAISE(ABORT,'SUPPLIER_INACTIVE'); END;
